const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dallasport = ee.Geometry.Point([-120.917, 45.719]); // Approximate coordinates for Dallasport, WA
  const medford = ee.Geometry.Point([-122.876, 42.326]);   // Approximate coordinates for Medford, OR

  const startDate = '2018-01-01'; // Recent period to capture potential heatwaves
  const endDate = '2023-12-31';

  const temperatureBand = 'mean_2m_air_temperature'; // Temperature in Kelvin

  // 2. Data Acquisition & Check
  const era5Land = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .select(temperatureBand);

  const colSize = era5Land.size().getInfo();
  if (colSize === 0) {
    console.log("No ERA5-Land data found for the specified period.");
    console.log("C1");
    return;
  }
  console.log(`ERA5-Land images in collection: ${colSize}`);

  // Calculate the maximum temperature over the entire period for each pixel
  // using qualityMosaic which selects the pixel with the maximum value for the specified band.
  const maxTempImage = era5Land.qualityMosaic(temperatureBand);

  // Function to extract temperature and convert to Fahrenheit
  const getTempFahrenheit = (location, locationName) => {
    const tempK = maxTempImage.reduceRegion({
      reducer: ee.Reducer.max(), // Use max reducer as qualityMosaic already finds max value for each pixel over time
      geometry: location,
      scale: 1000, // ERA5-Land resolution is ~9km, 1km scale is sufficient
      maxPixels: 1e9
    }).get(temperatureBand).getInfo();

    if (tempK === null || tempK === undefined) {
      console.log(`Calculation failure for ${locationName}: temperature value is null.`);
      return null;
    }

    // Convert Kelvin to Fahrenheit: (K - 273.15) * 9/5 + 32
    const tempF = (tempK - 273.15) * 9 / 5 + 32;
    return tempF;
  };

  // Get temperatures for Dallasport
  const dallasportTempF = getTempFahrenheit(dallasport, 'Dallasport');
  if (dallasportTempF === null) {
    console.log("C3");
    return;
  }
  console.log(`Max temp in Dallasport (2018-2023): ${dallasportTempF.toFixed(2)}°F`);

  // Get temperatures for Medford
  const medfordTempF = getTempFahrenheit(medford, 'Medford');
  if (medfordTempF === null) {
    console.log("C3");
    return;
  }
  console.log(`Max temp in Medford (2018-2023): ${medfordTempF.toFixed(2)}°F`);

  // 5. Validation & Final Answer
  const threshold = 105; // degrees Fahrenheit

  const dallasportAboveThreshold = dallasportTempF > threshold;
  const medfordAboveThreshold = medfordTempF > threshold;

  if (dallasportAboveThreshold || medfordAboveThreshold) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
